//! 🧪️ Original queued byte owners retain FIFO identity through retries, denial and cancellation.
use super::*;
fn fund(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn observed<T>(run:impl FnOnce()->(T,RetainedCloneProgress))->T{let((result,p),h)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result}
#[test]
fn original_outbox_retains_same_bytes_across_failed_attempts_and_recycles_paid_pages(){
 let f:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for cut in std::iter::once(None).chain(f["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut owner=OriginalBackboneOutbox::default();
  for _ in 0..f["cycles"].as_u64().unwrap(){let mut pointers=Vec::new();for row in f["messages"].as_array().unwrap(){let mut bytes=Some(OriginalBackboneMessageBytes::try_from_slice(row.as_str().unwrap().as_bytes()).unwrap());pointers.push(bytes.as_ref().unwrap().retained_bytes().backing_ptr(0).unwrap());loop{let d=owner.append_demands().unwrap();if owner.can_append(fund(d)).unwrap(){break}observed(||((),owner.reserve_step(fund(d)).unwrap()));}let d=owner.append_demands().unwrap();for axis in 0..5{let mut g=fund(d);let limit=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *limit==0{continue}*limit-=1;let len=owner.len();let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.append_reserved(&mut bytes,g).unwrap());assert!(result.is_none());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(owner.len(),len);assert!(bytes.is_some());}observed(||((),owner.append_reserved(&mut bytes,fund(d)).unwrap().unwrap()));assert!(bytes.is_none());}
   for (index,row)in f["messages"].as_array().unwrap().iter().enumerate(){if cut.is_some_and(|cut|index>=cut){break}for _ in 0..3{let front=owner.front().unwrap();assert_eq!(front.retained_bytes().backing_ptr(0).unwrap(),pointers[index]);assert_eq!(front.iter().collect::<Vec<_>>(),row.as_str().unwrap().as_bytes());}let d=owner.acknowledgement_demands().unwrap();observed(||((),owner.acknowledge_delivered(fund(d)).unwrap().unwrap()));while owner.has_delivered_retirement(){let d=owner.delivered_demands(4096).unwrap();observed(||{let step=owner.close_delivered_step(fund(d)).unwrap();((),step.progress())});}}
   if cut.is_some(){break}assert_eq!(owner.len(),0);for turn in 0..10000{if owner.terminal_is_empty(){break}let d=owner.recycle_demands(4096).unwrap();observed(||{let step=owner.recycle_step(fund(d)).unwrap();((),step.progress())});assert!(turn<9999);}
  }
  owner.begin_close();for turn in 0..10000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();observed(||{let step=owner.close_step(fund(d)).unwrap();((),step.progress())});assert!(turn<9999);}
 }
}
#[test]
fn installed_backbone_disposer_keeps_original_outbox_until_complete_native_admission(){
 let mut source=OriginalBackboneOutbox::default();let mut payload=Some(OriginalBackboneMessageBytes::try_from_slice("energy λ".as_bytes()).unwrap());let pointer=payload.as_ref().unwrap().retained_bytes().backing_ptr(0).unwrap();loop{let d=source.append_demands().unwrap();if source.can_append(fund(d)).unwrap(){break}observed(||((),source.reserve_step(fund(d)).unwrap()));}let d=source.append_demands().unwrap();observed(||((),source.append_reserved(&mut payload,fund(d)).unwrap().unwrap()));
 let d=crate::backbone_retirement::ArtifactStoreBackboneRetirement::original_outbox_birth_demands();for axis in 0..5{let mut g=fund(d);let limit=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *limit==0{continue}*limit-=1;let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||crate::backbone_retirement::ArtifactStoreBackboneRetirement::admit_original_outbox(&mut source,g).unwrap());assert!(result.0.is_none());assert_eq!(result.1,Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(source.front().unwrap().retained_bytes().backing_ptr(0).unwrap(),pointer);}
 let mut owner=observed(||crate::backbone_retirement::ArtifactStoreBackboneRetirement::admit_original_outbox(&mut source,fund(d)).unwrap());assert!(source.terminal_is_empty());for turn in 0..10000{if owner.is_none(){break}let d=semio_framework_value::factory_ticket_demands(owner.as_ref().unwrap(),4096).unwrap();observed(||{let step=semio_framework_value::close_factory_ticket(&mut owner,fund(d)).unwrap();((),step.progress())});assert!(turn<9999);}
}

#[test]
fn original_transport_moves_original_pages_once_and_retains_both_cancel_frontiers(){
 let law:serde_json::Value=serde_json::from_str(include_str!("transfer.json")).unwrap();let pattern=law["pattern"].as_array().unwrap();let bytes:Vec<_>=(0..law["bytes"].as_u64().unwrap()as usize).map(|i|pattern[i%pattern.len()].as_u64().unwrap()as u8).collect();
 for transfer in [false,true]{let mut source=OriginalBackboneOutbox::default();let mut recipient=OriginalBackboneOutbox::default();let mut payload=Some(OriginalBackboneMessageBytes::try_from_slice(&bytes).unwrap());let pointer=payload.as_ref().unwrap().retained_bytes().backing_ptr(0).unwrap();
  loop{let d=source.append_demands().unwrap();if source.can_append(fund(d)).unwrap(){break}observed(||((),source.reserve_step(fund(d)).unwrap()));}let d=source.append_demands().unwrap();observed(||((),source.append_reserved(&mut payload,fund(d)).unwrap().unwrap()));
  if transfer{for turn in 0..10000{let d=source.transfer_demands(&recipient).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);for axis in 0..5{let mut g=fund(d);let limit=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *limit==0{continue}*limit-=1;let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.transfer_step(&mut recipient,g).unwrap());assert!(result.is_none());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(source.front().unwrap().retained_bytes().backing_ptr(0).unwrap(),pointer);assert_eq!(recipient.len(),0);}let moved=observed(||{let(moved,p)=source.transfer_step(&mut recipient,fund(d)).unwrap().unwrap();(moved,p)});if moved{break}assert!(turn<9999);}assert_eq!(source.len(),law["expected"]["source"].as_u64().unwrap()as usize);assert_eq!(recipient.len(),law["expected"]["recipient"].as_u64().unwrap()as usize);assert_eq!(recipient.front().unwrap().retained_bytes().backing_ptr(0).unwrap(),pointer);assert_eq!(recipient.front().unwrap().to_vec_owner(),bytes);}else{assert_eq!(source.front().unwrap().retained_bytes().backing_ptr(0).unwrap(),pointer);assert_eq!(recipient.len(),0);}
  for owner in [&mut source,&mut recipient]{owner.begin_close();for turn in 0..10000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);observed(||{let step=owner.close_step(fund(d)).unwrap();((),step.progress())});assert!(turn<9999);}}
 }
}

#[test]
fn canonical_backbone_message_owns_original_paged_causal_bytes_and_closes_them(){
 let law:serde_json::Value=serde_json::from_str(include_str!("transfer.json")).unwrap();let pattern=law["pattern"].as_array().unwrap();let bytes:Vec<_>=(0..law["bytes"].as_u64().unwrap()as usize).map(|i|pattern[i%pattern.len()].as_u64().unwrap()as u8).collect();let payload=OriginalBackboneMessageBytes::try_from_slice(&bytes).unwrap();let pointer=payload.retained_bytes().backing_ptr(0).unwrap();let message=crate::BackboneMessage::Mutations{envelopes:payload};let crate::BackboneMessage::Mutations{envelopes}= &message else{unreachable!()};assert_eq!(envelopes.retained_bytes().backing_ptr(0).unwrap(),pointer);
 let encoded=semio_framework_os_spr::OpBinary::encode_op(&message).unwrap();assert_eq!(crate::decode_backbone_message_exact(&encoded).unwrap(),message);
 let mut queue=std::collections::VecDeque::new();queue.push_back(message);let mut owner=crate::backbone_retirement::ArtifactStoreBackboneRetirement::from_queue(queue);for turn in 0..10000{if semio_framework_value::ErasedSnapshotRetirement::terminal_is_empty(&owner){break}let d=owner.demands().unwrap();observed(||{let step=semio_framework_value::ErasedSnapshotRetirement::close_step(&mut owner,fund(d)).unwrap();((),step.progress())});assert!(turn<9999);}
}

#[test]
fn original_channel_donation_preserves_pages_and_all_denied_axes(){
 let law:serde_json::Value=serde_json::from_str(include_str!("transfer.json")).unwrap();let pattern=law["pattern"].as_array().unwrap();let bytes:Vec<_>=(0..law["bytes"].as_u64().unwrap()as usize).map(|i|pattern[i%pattern.len()].as_u64().unwrap()as u8).collect();
 for prefix in [0,2]{let mut source=OriginalBackboneOutbox::default();let mut queue=std::collections::VecDeque::new();queue.try_reserve_exact(prefix).unwrap();for _ in 0..prefix{queue.push_back(crate::BackboneMessage::Ack{op_ids:Vec::new()});}let mut payload=Some(OriginalBackboneMessageBytes::try_from_slice(&bytes).unwrap());let pointer=payload.as_ref().unwrap().retained_bytes().backing_ptr(0).unwrap();loop{let d=source.append_demands().unwrap();if source.can_append(fund(d)).unwrap(){break}observed(||((),source.reserve_step(fund(d)).unwrap()));}let d=source.append_demands().unwrap();observed(||((),source.append_reserved(&mut payload,fund(d)).unwrap().unwrap()));
  for turn in 0..10000{let d=source.channel_demands(&queue).unwrap().unwrap();for axis in 0..5{let mut g=fund(d);let limit=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *limit==0{continue}*limit-=1;let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.transfer_to_channel_step(&mut queue,g).unwrap());assert!(result.is_none());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(source.front().unwrap().retained_bytes().backing_ptr(0).unwrap(),pointer);assert_eq!(queue.len(),prefix);}let moved=observed(||{let(moved,p)=source.transfer_to_channel_step(&mut queue,fund(d)).unwrap().unwrap();(moved,p)});if moved{break}assert!(turn<9999);}
  assert_eq!(source.len(),0);assert_eq!(queue.len(),prefix+1);let Some(crate::BackboneMessage::Mutations{envelopes})=queue.back()else{panic!("actual channel owns its canonical mutation message")};assert_eq!(envelopes.retained_bytes().backing_ptr(0).unwrap(),pointer);assert_eq!(envelopes.to_vec_owner(),bytes);assert!(source.transfer_to_channel_step(&mut queue,RetainedCloneGrant::default()).unwrap().is_none());
  let mut owner=crate::backbone_retirement::ArtifactStoreBackboneRetirement::from_queue(queue);for turn in 0..10000{if semio_framework_value::ErasedSnapshotRetirement::terminal_is_empty(&owner){break}let d=owner.demands().unwrap();observed(||{let step=semio_framework_value::ErasedSnapshotRetirement::close_step(&mut owner,fund(d)).unwrap();((),step.progress())});assert!(turn<9999);}source.begin_close();for turn in 0..10000{if source.terminal_is_empty(){break}let d=source.close_demands(4096).unwrap();observed(||{let step=source.close_step(fund(d)).unwrap();((),step.progress())});assert!(turn<9999);}
 }
}
